package co.edu.unicauca.lisw2t5g02.domain.user;
import co.edu.unicauca.lisw2t5g02.exception.*;import co.edu.unicauca.lisw2t5g02.security.*;import java.util.List;
public class UserService {private final IUserRepository repo;private final IPasswordHasher hasher;public UserService(IUserRepository r,IPasswordHasher h){repo=r;hasher=h;}
 public User registerUser(String username,String name,String password,Role role){return registerUser(username,name,username+"@demo.local",password,role);}
 public User registerUser(String username,String name,String email,String password,Role role){if(username==null||username.isBlank()||name==null||name.isBlank()||role==null)throw new IllegalArgumentException("Usuario, nombre y rol son obligatorios.");if(repo.findByUsername(username).isPresent())throw new UserAlreadyExistsException(username);PasswordPolicy.validate(password);User u=new User();u.setUsername(username);u.setName(name);u.setEmail(email);u.setRole(role);u.setState(UserState.ACTIVO);u.setPasswordHash(hasher.hash(password));repo.create(u);return u;}
 public User updateUser(int id,String username,String name,Role role,String password){User u=repo.findById(id).orElseThrow(()->new UserNotFoundException("id="+id));if(username==null||username.isBlank()||name==null||name.isBlank()||role==null)throw new IllegalArgumentException("Datos obligatorios.");repo.findByUsername(username).filter(x->x.getId()!=id).ifPresent(x->{throw new UserAlreadyExistsException(username);});u.setUsername(username);u.setName(name);u.setRole(role);if(password!=null&&!password.isBlank()){PasswordPolicy.validate(password);u.setPasswordHash(hasher.hash(password));}repo.update(u);return u;}
 public User changeRole(int id,Role role){User u=repo.findById(id).orElseThrow(()->new UserNotFoundException("id="+id));u.setRole(role);repo.update(u);return u;}public User changeState(int id,UserState state){User u=repo.findById(id).orElseThrow(()->new UserNotFoundException("id="+id));u.setState(state);repo.update(u);return u;}public List<User> listUsers(){return repo.listAll();}public void deleteUser(int id){repo.delete(id);}}
